"use client";

import React, { createContext, useContext, useEffect, useState, useSyncExternalStore } from "react";
import { DEFAULT_PORTFOLIO, THEME_PRESETS } from "@/data/defaultPortfolio";
import { PortfolioConfig, PortfolioSettings, ProfileData, ProjectItem, SkillItem } from "@/types/portfolio";

const STORAGE_KEY = "lara_portfolio_studio_v1";

let cachedConfig: PortfolioConfig | null = null;
const listeners = new Set<() => void>();

function readClientConfig(): PortfolioConfig {
  if (cachedConfig) return cachedConfig;
  try {
    const saved = window.localStorage.getItem(STORAGE_KEY);
    if (saved) {
      const parsed = JSON.parse(saved) as Partial<PortfolioConfig>;
      if (parsed && parsed.profile && Array.isArray(parsed.skills) && Array.isArray(parsed.projects)) {
        cachedConfig = {
          ...DEFAULT_PORTFOLIO,
          ...parsed,
          profile: { ...DEFAULT_PORTFOLIO.profile, ...parsed.profile },
          settings: { ...DEFAULT_PORTFOLIO.settings, ...parsed.settings },
        };
        return cachedConfig;
      }
    }
  } catch {
    // Fall back cleanly to default config if stored JSON is malformed
  }
  cachedConfig = DEFAULT_PORTFOLIO;
  return cachedConfig;
}

function writeClientConfig(next: PortfolioConfig) {
  cachedConfig = next;
  try {
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(next));
  } catch {
    // Ignore quota errors in private browsing modes
  }
  listeners.forEach((l) => l());
}

function subscribeConfig(callback: () => void) {
  listeners.add(callback);
  const onStorage = (e: StorageEvent) => {
    if (e.key === STORAGE_KEY) {
      cachedConfig = null;
      callback();
    }
  };
  window.addEventListener("storage", onStorage);
  return () => {
    listeners.delete(callback);
    window.removeEventListener("storage", onStorage);
  };
}

const emptySubscribe = () => () => {};

interface PortfolioContextValue {
  config: PortfolioConfig;
  hydrated: boolean;
  studioOpen: boolean;
  setStudioOpen: (open: boolean) => void;
  studioTab: "profile" | "projects" | "skills" | "theme" | "export";
  setStudioTab: (tab: "profile" | "projects" | "skills" | "theme" | "export") => void;
  commandOpen: boolean;
  setCommandOpen: (open: boolean) => void;
  updateProfile: (patch: Partial<ProfileData>) => void;
  updateSettings: (patch: Partial<PortfolioSettings>) => void;
  upsertProject: (project: ProjectItem) => void;
  deleteProject: (id: string) => void;
  upsertSkill: (skill: SkillItem) => void;
  deleteSkill: (id: string) => void;
  importConfig: (rawJson: string) => { ok: boolean; error?: string };
  resetToDefault: () => void;
}

const PortfolioContext = createContext<PortfolioContextValue | null>(null);

export function PortfolioProvider({ children }: { children: React.ReactNode }) {
  const config = useSyncExternalStore(subscribeConfig, readClientConfig, () => DEFAULT_PORTFOLIO);
  const hydrated = useSyncExternalStore(emptySubscribe, () => true, () => false);
  const [studioOpen, setStudioOpen] = useState(false);
  const [studioTab, setStudioTab] = useState<"profile" | "projects" | "skills" | "theme" | "export">("profile");
  const [commandOpen, setCommandOpen] = useState(false);

  // Synchronize CSS theme variables
  useEffect(() => {
    const preset = THEME_PRESETS[config.settings.theme] ?? THEME_PRESETS.cryo;
    const root = document.documentElement;
    root.style.setProperty("--accent", preset.accent);
    root.style.setProperty("--accent-secondary", preset.accentSecondary);
    root.style.setProperty("--accent-glow", preset.glow);
  }, [config.settings.theme]);

  // Global Cmd/Ctrl+K shortcut for Command Palette
  useEffect(() => {
    const onKeyDown = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === "k") {
        e.preventDefault();
        setCommandOpen((prev) => !prev);
      }
    };
    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, []);

  const updateProfile = (patch: Partial<ProfileData>) => {
    const current = readClientConfig();
    writeClientConfig({
      ...current,
      profile: { ...current.profile, ...patch },
    });
  };

  const updateSettings = (patch: Partial<PortfolioSettings>) => {
    const current = readClientConfig();
    writeClientConfig({
      ...current,
      settings: { ...current.settings, ...patch },
    });
  };

  const upsertProject = (project: ProjectItem) => {
    const current = readClientConfig();
    const exists = current.projects.some((p) => p.id === project.id);
    const nextProjects = exists
      ? current.projects.map((p) => (p.id === project.id ? project : p))
      : [project, ...current.projects];
    writeClientConfig({ ...current, projects: nextProjects });
  };

  const deleteProject = (id: string) => {
    const current = readClientConfig();
    writeClientConfig({
      ...current,
      projects: current.projects.filter((p) => p.id !== id),
    });
  };

  const upsertSkill = (skill: SkillItem) => {
    const current = readClientConfig();
    const exists = current.skills.some((s) => s.id === skill.id);
    const nextSkills = exists
      ? current.skills.map((s) => (s.id === skill.id ? skill : s))
      : [skill, ...current.skills];
    writeClientConfig({ ...current, skills: nextSkills });
  };

  const deleteSkill = (id: string) => {
    const current = readClientConfig();
    writeClientConfig({
      ...current,
      skills: current.skills.filter((s) => s.id !== id),
    });
  };

  const importConfig = (rawJson: string): { ok: boolean; error?: string } => {
    try {
      const parsed = JSON.parse(rawJson) as PortfolioConfig;
      if (!parsed.profile?.name || !Array.isArray(parsed.skills) || !Array.isArray(parsed.projects)) {
        return { ok: false, error: "Invalid portfolio schema: missing profile, skills, or projects." };
      }
      writeClientConfig({
        ...DEFAULT_PORTFOLIO,
        ...parsed,
        profile: { ...DEFAULT_PORTFOLIO.profile, ...parsed.profile },
        settings: { ...DEFAULT_PORTFOLIO.settings, ...parsed.settings },
      });
      return { ok: true };
    } catch (err) {
      return {
        ok: false,
        error: err instanceof Error ? err.message : "Could not parse JSON configuration.",
      };
    }
  };

  const resetToDefault = () => {
    cachedConfig = DEFAULT_PORTFOLIO;
    try {
      window.localStorage.removeItem(STORAGE_KEY);
    } catch {
      // Ignore
    }
    listeners.forEach((l) => l());
  };

  return (
    <PortfolioContext.Provider
      value={{
        config,
        hydrated,
        studioOpen,
        setStudioOpen,
        studioTab,
        setStudioTab,
        commandOpen,
        setCommandOpen,
        updateProfile,
        updateSettings,
        upsertProject,
        deleteProject,
        upsertSkill,
        deleteSkill,
        importConfig,
        resetToDefault,
      }}
    >
      {children}
    </PortfolioContext.Provider>
  );
}

export function usePortfolio() {
  const ctx = useContext(PortfolioContext);
  if (!ctx) {
    throw new Error("usePortfolio must be used within a PortfolioProvider");
  }
  return ctx;
}
